C     Errors in one program: each is reported, and the parse goes on.
      PROGRAM ERRORS
      INTEGER I, J(
      X = (A + B
      READ *, X
      DO 10 I 1, 5
   10 CONTINUE 5
      IF (X .GT. 0) DO 20 I = 1, 2
   20 GO TO 0
      CALL S(A,
     1       B
      PRINT *, 'OK'
      SUBROUTINE S(A, B)
      A = 5HHELLO
      END
      X = 1
